    }

    // 预警
    var alerts = []
    var rawAlerts = data.data.alerts || []
    for (var k = 0; k < rawAlerts.length; k++) {
      alerts.push(rawAlerts[k].type + rawAlerts[k].level)
    }

    return {
      ready: true,
      title: district,
      subtitle: desc,
      message: temp + "°C",
      details: [
